 183→/// Diagnostic: owner page bootstrap creates protocol sync-meta layer locally.
 184→#[tokio::test]
 185→async fn diagnostic_owner_page_bootstrap_creates_sync_meta_layer() -> Result<()> {
 186→    init_tracing();
 187→
 188→    let mut s = Scenario::builder()
 189→        .app("osvauld-demos")
 190→        .published()
 191→        .build()
 192→        .await?;
 193→
 194→    let page_id = s.space().page_id.clone();
 195→    let owner_did = s.owner().butler.user_info().await?.did;
 196→    let sync_meta_layer = format!("__sync_meta/{}", owner_did);
 197→    let owner_page = s
 198→        .owner()
 199→        .butler
 200→        .pages()
 201→        .get(&page_id)?
 202→        .expect("owner should have page");
 203→    let owner_permit = owner_page
 204→        .permit
 205→        .clone()
 206→        .expect("owner page should have permit");
 207→    let parsed_owner_permit = gurkha::Permit::from_token(&owner_permit)?;
 208→    let expected_sync_layers = expected_sync_layers_from_permit(&parsed_owner_permit, &page_id);
 209→
 210→    wait_until("owner sync-meta layer exists", Duration::from_secs(5), || {
 211→        s.owner()
 212→            .butler
 213→            .store()
 214→            .get_layer(&page_id, &sync_meta_layer)
 215→            .ok()
 216→            .flatten()
 217→    })
 218→    .await?;
 219→
 220→    let owner_sync_meta_json = get_layer_json(s.owner(), &page_id, &sync_meta_layer).await?;
 221→    assert_sync_meta_entries(&owner_sync_meta_json, &expected_sync_layers);
 222→
 223→    wait_until("node sync-meta layer exists", Duration::from_secs(10), || {
 224→        s.node()
 225→            .butler
 226→            .store()
 227→            .get_all_layers(&page_id)
 228→            .ok()
 229→            .and_then(|layers| {
 230→                layers
 231→                    .into_iter()
 232→                    .find(|(name, _)| name == &sync_meta_layer)
 233→                    .map(|(_, data)| data)
 234→            })
 235→    })
 236→    .await?;
 237→
 238→    let node_sync_meta_json = get_layer_json(s.node(), &page_id, &sync_meta_layer).await?;
 239→    assert_sync_meta_entries(&node_sync_meta_json, &expected_sync_layers);
 240→
 241→    s.shutdown().await;
 242→    Ok(())
 243→}
