 314→/// Viewer connects to node and receives page with encrypted key
 315→///
 316→/// **Bug coverage**: SpaceData carries Vec<PublishedPageMeta> and the viewer
 317→/// creates page shells with generated AES keys. Verifies viewer-side page creation.
 318→#[tokio::test]
 319→async fn test_viewer_receives_page() -> Result<()> {
 320→    init_tracing();
 321→
 322→    let mut s = Scenario::builder()
 323→        .app("osvauld-demos")
 324→        .published()
 325→        .viewers(1)
 326→        .build()
 327→        .await?;
 328→
 329→    let page_id = s.space().page_id.clone();
 330→    let space_id = s.space().space_id.clone();
 331→
 332→    sleep(Duration::from_millis(500)).await;
 333→
 334→    // Get viewer link and add viewer
 335→    let viewer_link = s.get_viewer_link(&space_id).await?;
 336→    s.add_viewer(0, &viewer_link, &page_id).await?;
 337→
 338→    // Verify viewer has the page
 339→    let viewer_page = s.viewer(0).butler.pages().get(&page_id)?;
