  1→//! Apply update handling for Scribe actor
  2→//!
  3→//! Handles incoming layer updates (local or remote), including permission checks,
  4→//! validation, and CRDT merge.
  5→//!
  6→//! Note: Derivation is now handled externally by kunki/LuaRuntime which
  7→//! subscribes to PageUpdate::LayerChanged events.
  8→//!
  9→//! ## Key Types
 10→//!
 11→//! - `UpdateContext`: Computed context for an incoming update - all decisions made upfront
 12→//! - `ApplyOutcome`: Result of applying an update (Applied or Rejected)
 13→
 14→use logging_utils::ShortLayer;
 15→use tracing::{debug, error, info, warn, instrument};
 16→
 17→use domains::Layer;
 18→
 19→use super::broadcast::{broadcast_update, notify_layer_discovered};
 20→use crate::layer_unit::LayerUnit;
 21→use crate::layer_unit::{find_matching_dynamic_schema, prepare_layer_permits};
 22→use crate::loro_observer::{set_pending_update_source, clear_pending_update_source, setup_layer_observer};
 23→use crate::permit::{Permissions, PermitContext};
 24→use crate::state::ScribeState;
 25→use crate::SyncEvent;
 26→use crate::JsonOp;
 27→use crate::state::normalize_layer_name;
 28→
 29→// Update Context - Centralized Decision Logic
 30→
 31→/// Context for an incoming update - computed once, used throughout
 32→///
 33→/// **Design**: All decisions about how to handle an update are computed upfront.
 34→/// This makes the apply flow clearer and easier to test.
 35→#[derive(Debug)]
 36→pub struct UpdateContext {
 37→    /// Layer being updated
 38→    pub layer_name: String,
 39→    /// Source of update: None = local, Some = remote peer (user_did, device_id)
 40→    pub from_peer: Option<(String, String)>,
 41→    /// Role of the peer (for validation) - "node", "owner", "viewer", etc.
 42→    pub peer_role: String,
 43→
 44→    /// Is this a remote update (from a peer)?
 45→    pub is_remote: bool,
 46→    /// Is this layer local-only (never synced)?
 47→    pub is_local_only: bool,
 48→    /// Does this update need Lua validation?
 49→    pub should_validate: bool,
 50→    /// Should we broadcast after applying?
 51→    pub should_broadcast: bool,
 52→    /// Is this a new layer (needs creation)?
 53→    pub is_new_layer: bool,
 54→}
 55→
 56→impl UpdateContext {
 57→    /// Create context for an incoming update
 58→    ///
 59→    /// **Context**: Computes all decisions based on state and update metadata
 60→    /// **Note**: Permission checks are done separately (may reject before context is useful)
 61→    pub fn new(
 62→        state: &ScribeState,
 63→        layer_name: &str,
 64→        from_peer: Option<(String, String)>,
 65→    ) -> Self {
 66→        let is_remote = from_peer.is_some();
 67→        let is_local_only = Permissions::is_local_only(layer_name);
 68→        let is_new_layer = !state.units.contains_key(layer_name);
 69→
 70→        // Determine peer role for validation
 71→        let peer_role = if let Some(ref peer) = from_peer {
 72→            get_peer_role(state, &peer.0)
 73→        } else {
 74→            "local".to_string()
 75→        };
 76→
 77→        // Should validate: remote update AND ValidationHandle exists
 78→        let should_validate = is_remote && state.validation_handle.is_some();
 79→
 80→        // Should broadcast: remote update (local updates use observer)
 81→        let should_broadcast = is_remote;
 82→
 83→        Self {
 84→            layer_name: layer_name.to_string(),
 85→            from_peer,
 86→            peer_role,
 87→            is_remote,
 88→            is_local_only,
 89→            should_validate,
 90→            should_broadcast,
 91→            is_new_layer,
 92→        }
 93→    }
 94→}
 95→
 96→// Apply Outcome - Event-Driven Pattern
 97→
 98→/// Outcome of applying an update
 99→///
100→/// **Design**: Separates the "what happened" from "what to do next"
101→/// This enables cleaner outcome handling and better error messages
102→#[derive(Debug)]
103→pub enum ApplyOutcome {
104→    /// Update was successfully applied
105→    Applied {
106→        /// Layer that was updated
107→        layer_name: String,
108→        /// Ops extracted from update (for derivation)
109→        ops: Vec<JsonOp>,
110→        /// Was a new layer created?
111→        created_layer: bool,
112→    },
113→    /// Update was rejected
114→    Rejected {
115→        /// Reason for rejection
116→        reason: String,
117→    },
118→}
119→
120→// Apply Update Handler
121→
122→/// Handle layer update (local or remote)
123→///
124→/// **Context**: Edit from UI or sync push from peer
125→/// **We do**: Permission check, validation, CRDT merge
126→/// **Broadcast**: Handled automatically by Loro observer (set up at startup)
127→/// **Returns**: Ok(()) on success, Err(message) on failure
128→#[instrument(skip(state, update, permit), fields(page_id = %state.page_id, layer = %ShortLayer(layer_name)))]
129→pub async fn handle_apply_update(
130→    state: &mut ScribeState,
131→    layer_name: &str,
132→    update: &[u8],
133→    from_peer: Option<(String, String)>,
134→    permit: Option<&str>,
135→) -> std::result::Result<(), String> {
136→    let _ = permit; // Permit is used for subscription in Courier, not here
137→
138→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
139→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
140→    let layer_name = layer_name.as_str();
141→
142→    // Build context - computes all decisions upfront
143→    let ctx = UpdateContext::new(state, layer_name, from_peer.clone());
144→
145→    // Step 1: Apply the update (with permission checks, validation, CRDT merge)
146→    let outcome = apply_update_core(state, &ctx, update).await;
147→
148→    // Step 2: Handle the outcome
149→    let from_peer_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str());
150→    match outcome {
151→        ApplyOutcome::Applied { layer_name, ops: _, created_layer } => {
152→            // Mark layer as dirty for persistence
153→            if let Some(unit) = state.units.get_mut(&layer_name) {
154→                unit.mark_dirty();
155→            }
156→            debug!(layer = %layer_name, created = created_layer, "Update applied successfully");
157→            state.emit_apply_update_capture(&layer_name, from_peer_did, "applied", None);
158→
159→            // Post-apply handling for remote updates
160→            if ctx.is_remote {
161→                handle_post_apply(state, &layer_name, ctx.from_peer.clone()).await;
162→            }
163→
164→            // Node-side: detect new dynamic layers and issue permits
165→            if created_layer {
166→                if let Some(ref from_peer) = ctx.from_peer {
167→                    emit_dynamic_layer_permits(state, &layer_name, from_peer).await;
168→                }
169→            }
170→
171→            // Update sender's vector
172→            if let Some(ref peer) = ctx.from_peer {
173→                update_sender_vector(state, peer, &layer_name);
174→            }
175→
176→            // Broadcast to eligible subscribers
177→            if ctx.should_broadcast {
178→                broadcast_update(state, &layer_name, ctx.from_peer.as_ref()).await;
179→            }
180→
181→            // Note: Derivation is now handled externally by kunki/LuaRuntime
182→            // which subscribes to PageUpdate::LayerChanged events
183→
184→            Ok(())
185→        }
186→        ApplyOutcome::Rejected { reason } => {
187→            warn!(layer = %layer_name, reason = %reason, "Update rejected");
188→            state.emit_apply_update_capture(layer_name, from_peer_did, "rejected", Some(&reason));
189→            Err(reason)
190→        }
191→    }
192→}
193→
194→/// Core apply logic - returns ApplyOutcome
195→///
196→/// **Context**: Separated from handle_apply_update for cleaner testing
197→/// **Returns**: ApplyOutcome::Applied or ApplyOutcome::Rejected
198→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
199→async fn apply_update_core(
200→    state: &mut ScribeState,
201→    ctx: &UpdateContext,
202→    update: &[u8],
203→) -> ApplyOutcome {
204→    // Step 1: Permission check - reject local_only layers from remote
205→    if ctx.is_remote && ctx.is_local_only {
206→        return ApplyOutcome::Rejected {
207→            reason: "local_only layer cannot be updated by remote peer".to_string(),
208→        };
209→    }
210→
211→    // Step 2: Permission check for remote updates
212→    if let Some(ref peer) = ctx.from_peer {
213→        if !Permissions::can_write(state, peer, &ctx.layer_name) {
214→            return ApplyOutcome::Rejected {
215→                reason: "Permission denied: cannot write to layer".to_string(),
216→            };
217→        }
218→    }
219→
220→    // Step 3: Extract ops for validation (using optimized pre-commit method)
221→    let extracted_ops = if ctx.should_validate {
222→        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
223→        match Layer::extract_ops_from_bytes(update) {
224→            Ok(ops) => Some(ops),
225→            Err(e) => {
226→                // Log extraction failure - validation will proceed with empty ops
227→                // This could mask invalid updates, so log at warn level
228→                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
229→                None
230→            }
231→        }
232→    } else {
233→        None
234→    };
235→
236→    // Step 4: Validate with Lua (if needed)
237→    if ctx.should_validate {
238→        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
239→            return ApplyOutcome::Rejected { reason: e };
240→        }
241→    }
242→
243→    // Step 5: Create layer if needed (remote only)
244→    let created_layer = if ctx.is_new_layer {
245→        if ctx.is_remote {
246→            create_layer_from_peer(state, &ctx.layer_name);
247→            true
248→        } else {
249→            return ApplyOutcome::Rejected {
250→                reason: "Layer not found".to_string(),
251→            };
252→        }
253→    } else {
254→        false
255→    };
256→
257→    // Step 6: Apply CRDT update
258→    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
259→        return ApplyOutcome::Rejected { reason: e };
260→    }
261→
262→    ApplyOutcome::Applied {
263→        layer_name: ctx.layer_name.clone(),
264→        ops: extracted_ops.unwrap_or_default(),
265→        created_layer,
266→    }
267→}
268→
269→// Helper Functions
270→
271→/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
272→///
273→/// **Context**: Business logic validation for remote updates
274→/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
275→/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
276→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
277→async fn validate_update_with_context(
278→    state: &ScribeState,
279→    ctx: &UpdateContext,
280→    extracted_ops: &Option<Vec<JsonOp>>,
281→) -> Result<(), String> {
282→    let Some(ref ops) = extracted_ops else {
283→        return Ok(()); // No ops to validate
284→    };
285→
286→    if ops.is_empty() {
287→        return Ok(()); // Empty ops = nothing to validate
288→    }
289→
290→    // Extract actual DID from from_peer, not the role
291→    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");
292→
293→    // Use ValidationHandle (kunki mode with presence_lib)
294→    let Some(ref validation_handle) = state.validation_handle else {
295→        // No validation available - allow update (viewer/owner mode without kunki)
296→        // This is expected in viewer/owner mode but unexpected in node mode without kunki
297→        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
298→        return Ok(());
299→    };
300→
301→    use tokio::time::{timeout, Duration};
302→
303→    let validation_future = validation_handle.validate_ops(
304→        &state.page_id,
305→        &ctx.layer_name,
306→        ops,
307→        from_did,
308→        &ctx.peer_role,
309→    );
310→
311→    match timeout(Duration::from_secs(5), validation_future).await {
312→        Ok(Ok((true, _))) => {
313→            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
314→            Ok(())
315→        }
316→        Ok(Ok((false, error_msg))) => {
317→            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
318→            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
319→            Err(format!("Validation failed: {}", msg))
320→        }
321→        Ok(Err(e)) => {
322→            warn!(layer = %ctx.layer_name, error = %e, "Validation error, rejecting update");
323→            Err(format!("Validation error: {}", e))
324→        }
325→        Err(_) => {
326→            warn!(layer = %ctx.layer_name, "Validation timeout (5s), rejecting update");
327→            Err("Validation timeout".to_string())
328→        }
329→    }
330→}
331→
332→/// Create a new layer from peer sync
333→///
334→/// **Context**: Peer sent update for a layer we don't have yet
335→/// **We do**: Create layer, set up observer, notify UI
336→#[instrument(skip(state), fields(page_id = %state.page_id))]
337→fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
338→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
339→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
340→    let layer_name = layer_name.as_str();
341→    let mut unit = LayerUnit::new_empty();
342→    unit.set_local_only(!state.should_sync_layer(layer_name));
343→    unit.mark_dirty();
344→    state.units.insert(layer_name.to_string(), unit);
345→    info!(layer = %layer_name, "Created new layer from peer sync");
346→
347→    // Authorize existing subscribers for this new layer
348→    if let Ok(subs) = state.subscribers.read() {
349→        for ((did, _), info) in subs.iter() {
350→            if info.can_receive_layer(layer_name, &state.page_id) {
351→                if let Some(unit) = state.units.get(layer_name) {
352→                    unit.authorize_did(did);
353→                    state.emit_layer_auth_capture(layer_name, did, "authorized_subscriber");
354→                }
355→            }
356→        }
357→    }
358→
359→    // Apply any pending authorizations (from AuthorizeLayerSubscriber before layer creation)
360→    if let Some(pending_dids) = state.pending_layer_authorizations.remove(layer_name) {
361→        if let Some(unit) = state.units.get(layer_name) {
362→            for did in &pending_dids {
363→                unit.authorize_did(did);
364→                state.emit_layer_auth_capture(layer_name, did, "applied_pending");
365→                info!(layer = %layer_name, did = %did, "Applied pending layer authorization");
366→            }
367→        }
368→    }
369→
370→    // Set up Loro observer for new layer to enable sync broadcasts
371→    setup_layer_observer(state, layer_name);
372→
373→    // Notify UI subscribers about the new layer
374→    notify_layer_discovered(state, layer_name);
375→}
376→
377→/// Apply CRDT update to layer
378→///
379→/// **Context**: Actually merge the update into the layer
380→/// **We do**: Set pending source, apply, clear pending source
381→#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
382→fn apply_crdt_update(
383→    state: &mut ScribeState,
384→    layer_name: &str,
385→    update: &[u8],
386→    from_peer: Option<(String, String)>,
387→) -> Result<(), String> {
388→    // Set pending update source BEFORE apply() so observer knows who caused this change
389→    set_pending_update_source(state, from_peer);
390→
391→    // Get the layer and apply update
392→    let result = if let Some(unit) = state.units.get(layer_name) {
393→        unit.layer().apply(update)
394→    } else {
395→        clear_pending_update_source(state);
396→        return Err("Layer not found".to_string());
397→    };
398→
399→    if let Err(e) = result {
400→        // Clear on error too
401→        clear_pending_update_source(state);
402→        error!(error = %e, "Failed to apply update to layer");
403→        return Err(format!("Failed to apply update: {}", e));
404→    }
405→
406→    // Clear pending update source AFTER apply() (observer already captured it)
407→    clear_pending_update_source(state);
408→
409→    Ok(())
410→}
411→
412→/// Handle post-apply actions for remote updates
413→///
414→/// **Context**: Remote update was successfully applied
415→/// **We do**: Flush app layers immediately
416→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
417→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
418→async fn handle_post_apply(
419→    state: &mut ScribeState,
420→    layer_name: &str,
421→    _from_peer: Option<(String, String)>,
422→) {
423→    // For app layers, flush immediately to storage so restart loads new code
424→    if layer_name.starts_with("app:") {
425→        if let Some(unit) = state.units.get_mut(layer_name) {
426→            let snapshot = unit.layer().export_snapshot();
427→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
428→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
429→            } else {
430→                info!(layer = %layer_name, "Saved app layer immediately for restart");
431→                // Remove from dirty since we just saved it
432→                unit.clear_dirty();
433→            }
434→        }
435→    }
436→
437→    // Note: UI notification via emit_layer_changed_after_apply was removed
438→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
439→    // This prevents duplicate notifications
440→}
441→
442→/// Update sender's peer vector after receiving their update
443→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
444→fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
445→    if let Some(unit) = state.units.get(layer_name) {
446→        if let Ok(mut subs) = state.subscribers.write() {
447→            if let Some(info) = subs.get_mut(peer) {
448→                let current_vector = unit.layer().version_vector();
449→                info.vectors.insert(layer_name.to_string(), current_vector);
450→                debug!(user_did = %peer.0, "Updated sender's peer vector");
451→            }
452→        }
453→    }
454→}
455→
456→/// Detect if a newly created layer matches a dynamic schema and emit permits
457→///
458→/// **Context**: Node receives a new layer from peer via sync. If it matches a dynamic
459→/// schema, prepare layer permits and emit NewDynamicLayer for distribution.
460→/// **Offline-first**: Discovery happens via `__sync_meta/` — the creator already wrote
461→/// their sync_meta entry, and the node fans out `__sync_meta/{viewer_did}` entries
462→/// via `fanout_sync_meta_from_authority()` in Courier when the authority permit is present.
463→/// No direct broadcast authorization — same path for online and offline peers.
464→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
465→async fn emit_dynamic_layer_permits(
466→    state: &ScribeState,
467→    layer_name: &str,
468→    from_peer: &(String, String),
469→) {
470→    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
471→    let Some(ref permit_issuer) = state.permit_issuer else { return; };
472→    let Some(ref our_permit) = state.our_permit else { return; };
473→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
474→
475→    // Check if layer matches a dynamic schema
476→    let Some((schema_key, schema, creator_did)) =
477→        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };
478→
479→    // Validate creator namespace: sender's DID must match DID in path
480→    if from_peer.0 != creator_did {
481→        warn!(
482→            layer = %layer_name,
483→            sender = %from_peer.0,
484→            creator = %creator_did,
485→            "Creator namespace mismatch — sender DID doesn't match path DID"
486→        );
487→        return;
488→    }
489→
490→    // Collect connected peers with their roles
491→    let connected_peers = collect_connected_peers_with_roles(state);
492→
493→    // Prepare layer permits
494→    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
495→    match prepare_layer_permits(
496→        permit_issuer.as_ref(),
497→        &state.page_id,
498→        &full_layer_name,
499→        schema,
500→        &creator_did,
501→        &connected_peers,
502→    ) {
503→        Ok(permits) if !permits.is_empty() => {
504→            info!(
505→                layer = %layer_name,
506→                schema = %schema_key,
507→                creator = %creator_did,
508→                permit_count = permits.len(),
509→                "Prepared dynamic layer permits, emitting NewDynamicLayer"
510→            );
511→
512→            // Authorize each permit recipient on the channel LayerUnit so the
513→            // node's Scribe broadcast system includes them.  Discovery is still
514→            // via __sync_meta/ (offline-first), but broadcast requires authorized_dids.
515→            for (did, _token) in &permits {
516→                if let Some(unit) = state.units.get(layer_name) {
517→                    unit.authorize_did(did);
518→                    state.emit_layer_auth_capture(layer_name, did, "authorized_dynamic_permit");
519→                }
520→            }
521→
522→            let event = SyncEvent::NewDynamicLayer {
523→                page_id: state.page_id.clone(),
524→                layer_name: full_layer_name,
525→                permits,
526→            };
527→
528→            state.emit_sync_event_capture(&event);
529→            if let Err(e) = sync_event_tx.send(event).await {
530→                error!(error = %e, "Failed to emit NewDynamicLayer event");
531→            }
532→        }
533→        Ok(_) => {
534→            debug!(layer = %layer_name, "No permits needed for dynamic layer");
535→        }
536→        Err(e) => {
537→            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
538→        }
539→    }
540→}
541→
542→/// Collect connected peers with their roles from subscriber info
543→///
544→/// **Context**: Node needs (did, role) pairs for prepare_layer_permits
545→fn collect_connected_peers_with_roles(state: &ScribeState) -> Vec<(String, String)> {
546→    let mut peers = Vec::new();
547→
548→    if let Ok(subs) = state.subscribers.read() {
549→        for ((did, _device_id), info) in subs.iter() {
550→            let role = info.permit.relationship().unwrap_or("peer").to_string();
551→            // Avoid duplicates (same DID, different devices)
552→            if !peers.iter().any(|(d, _): &(String, String)| d == did) {
553→                peers.push((did.clone(), role));
554→            }
555→        }
556→    }
557→
558→    peers
559→}
560→
561→/// Get role for a peer from their stored permit
562→///
563→/// **Context**: Determining role for Lua validation
564→/// **Checks**:
565→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
566→/// 2. Stored permit (node mode) -> extract role from permit
567→/// 3. Default -> "peer"
568→#[instrument(skip(state), fields(page_id = %state.page_id))]
569→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
570→    // If peer is our sync target, they are the "node" from our perspective
571→    if let Some(ref config) = state.sync_config {
572→        if let Some(ref sync_target) = config.sync_target {
573→            if sync_target == peer_did {
574→                return "node".to_string();
575→            }
576→        }
577→    }
578→
579→    // Node mode: look up peer's stored permit and extract role via PermitContext
580→    if let Some(ref resolver) = state.peer_resolver {
581→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
582→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
583→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
584→                .unwrap_or_else(|_| "peer".to_string());
585→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
586→            return role;
587→        }
588→    }
589→
590→    // Default role
591→    "peer".to_string()
592→}
593→

