                "layer": layer,
                "layer_short": layer_short(layer),
                "peer_did": peer_did,
                "short_did": short_did(peer_did),
                "decision": "skip",
                "reason": reason,
            })) {
                let _ = tx.send(json);
            }
        }
    }
