  1→//! Typed CRDT operation handlers
  2→//!
  3→//! Handles list, map, and counter operations for Scribe actor.
  4→//! **Broadcast**: Handled automatically by Loro observer after commit()
  5→//!
  6→//! **Path convention**:
  7→//! - Empty path ("") = use layer_name as container name directly (Lua bindings)
  8→//! - Non-empty path = use root map pattern with nested containers (template actions)
  9→
 10→use tracing::{debug, info, instrument};
 11→
 12→use crate::{ScribeError, Result};
 13→use domains::json_to_loro_value;
 14→
 15→use crate::layer_unit::LayerUnit;
 16→use crate::state::ScribeState;
 17→use crate::loro_observer;
 18→
 19→// Typed CRDT Operation Handlers
 20→
 21→/// Helper to ensure a layer exists, returns true if layer was newly created
 22→fn ensure_layer_exists(state: &mut ScribeState, layer_name: &str) -> bool {
 23→    let is_new = !state.units.contains_key(layer_name);
 24→    if is_new {
 25→        let mut unit = LayerUnit::new_empty();
 26→        unit.set_local_only(!state.should_sync_layer(layer_name));
 27→        state.units.insert(layer_name.to_string(), unit);
 28→        state.track_new_sync_layer_in_meta(layer_name);
 29→        debug!(layer = %layer_name, "Created new layer");
 30→    }
 31→
 32→    // Auto-authorize target DID on __sync_meta/{did} layers so node-side
 33→    // writes (e.g. fanout) can broadcast to the intended recipient.
 34→    if let Some(target_did) = layer_name.strip_prefix("__sync_meta/") {
 35→        if let Some(unit) = state.units.get(layer_name) {
 36→            unit.authorize_did(target_did);
 37→        }
 38→    }
 39→
 40→    is_new
 41→}
 42→
 43→/// Handle list push operation (append)
 44→///
 45→/// **Broadcast**: Loro observer triggers broadcast after commit()
 46→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
 47→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
 48→pub async fn handle_list_push(
 49→    state: &mut ScribeState,
 50→    layer_name: &str,
 51→    path: &str,
 52→    item: serde_json::Value,
 53→) -> Result<()> {
 54→    info!("ListPush operation");
 55→
 56→    // Ensure layer exists
 57→    let is_new_layer = ensure_layer_exists(state, layer_name);
 58→
 59→    let unit = state.units.get_mut(layer_name)
 60→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
 61→
 62→    if path.is_empty() {
 63→        // Lua pattern: use layer_name as container name directly
 64→        let list = unit.layer().loro().get_list(layer_name);
 65→        let loro_value = json_to_loro_value(&item);
 66→        list.push(loro_value)
 67→            .map_err(|e| ScribeError::CrdtError(format!("ListPush: {}", e)))?;
 68→        unit.layer().commit();
 69→    } else {
 70→        // Template pattern: use root map with nested path
 71→        unit.layer().list_push(path, &item)
 72→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
 73→    }
 74→
 75→    unit.mark_dirty();
 76→
 77→    // Set up observer if new layer (after first write)
 78→    if is_new_layer {
 79→        loro_observer::setup_layer_observer(state, layer_name);
 80→    }
 81→
 82→    Ok(())
 83→}
 84→
 85→/// Handle list insert operation
 86→///
 87→/// **Broadcast**: Loro observer triggers broadcast after commit()
 88→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
 89→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
 90→pub async fn handle_list_insert(
 91→    state: &mut ScribeState,
 92→    layer_name: &str,
 93→    path: &str,
 94→    index: usize,
 95→    item: serde_json::Value,
 96→) -> Result<()> {
 97→    info!("ListInsert operation");
 98→
 99→    let is_new_layer = ensure_layer_exists(state, layer_name);
100→
101→    let unit = state.units.get_mut(layer_name)
102→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
103→
104→    if path.is_empty() {
105→        // Lua pattern: use layer_name as container name directly
106→        let list = unit.layer().loro().get_list(layer_name);
107→        let loro_value = json_to_loro_value(&item);
108→        list.insert(index, loro_value)
109→            .map_err(|e| ScribeError::CrdtError(format!("ListInsert: {}", e)))?;
