info!(layer = %layer_name, "Layer replaced successfully");

if is_new {
    // Authorize ALL existing subscribers for this new layer.
    // ReplaceLayer is called from SyncSnapshot (authoritative reset),
    // meaning the remote peer sent us this layer — all connected
    // peers should be able to receive our writes back.
    // can_receive_layer only checks the page permit (not layer permits),
    // so it fails for dynamic layers. Authorize unconditionally.
    if let Ok(subs) = state.subscribers.read() {
        for ((did, _), _info) in subs.iter() {
            if let Some(unit) = state.units.get(&layer_name) {
                unit.authorize_did(did);
                info!(layer = %layer_name, did = %did, "Authorized subscriber for new ReplaceLayer");
            }
        }
    }

    // Apply any pending authorizations
    if let Some(pending_dids) = state.pending_layer_authorizations.remove(&layer_name) {
        if let Some(unit) = state.units.get(&layer_name) {
            for did in &pending_dids {
                unit.authorize_did(did);
                info!(layer = %layer_name, did = %did, "Applied pending layer authorization");
            }
        }
    }

    // Set up Loro observer so future changes emit page_update events
    loro_observer::setup_layer_observer(state, &layer_name);

    // Notify UI about the discovered layer
    sync::broadcast::notify_layer_discovered(state, &layer_name);
}

