  1→//! 3-Step Sync Protocol
  2→//!
  3→//! Handles the SyncOffer → SyncAccept → SyncAck protocol for CRDT synchronization.
  4→//! Also includes asset sync triggering after layer sync completes.
  5→//!
  6→//! ## Bounded Resync Protocol
  7→//!
  8→//! When vectors diverge after SyncOffer/SyncAccept, we resync. But to prevent
  9→//! infinite loops, we track resync attempts:
 10→//!
 11→//! 1. `resync_attempts < MAX_RESYNC_ATTEMPTS`: Send another SyncOffer
 12→//! 2. `resync_attempts >= MAX_RESYNC_ATTEMPTS`: Send SyncReset (request full snapshot)
 13→//! 3. Node responds with SyncSnapshot (authoritative full state)
 14→//! 4. User replaces local layer entirely
 15→//!
 16→//! **Invariant**: Node is source of truth for divergence resolution.
 17→
 18→use tracing::{debug, error, info, trace, warn, instrument};
 19→use std::collections::BTreeSet;
 20→
 21→use crate::message::*;
 22→use transport::Connection;
 23→
 24→use super::super::guards::require_auth;
 25→use super::super::{PeerActor, PeerActorState, MAX_RESYNC_ATTEMPTS};
 26→
 27→impl<C: Connection> PeerActor<C> {
 28→
 29→    fn is_sync_meta_layer(page_id: &str, layer_name: &str) -> bool {
 30→        layer_name.starts_with("__sync_meta/")
 31→            || layer_name.starts_with(&format!("{}/__sync_meta/", page_id))
 32→    }
 33→
 34→    fn authority_schema_for_layer<'a>(
 35→        permit: &'a gurkha::Permit,
 36→        page_id: &str,
 37→        layer_name: &str,
 38→    ) -> Option<&'a gurkha::DynamicLayerSchema> {
 39→        let schemas = permit.dynamic_layer_schemas();
 40→        if schemas.is_empty() {
 41→            return None;
 42→        }
 43→
 44→        let bare_path = layer_name
 45→            .strip_prefix(&format!("{}/", page_id))
 46→            .unwrap_or(layer_name);
 47→        let path_parts: Vec<&str> = bare_path.split('/').collect();
 48→        if path_parts.len() < 3 || !path_parts[1].starts_with("did:") {
 49→            return None;
 50→        }
 51→
 52→        for (schema_key, schema) in schemas {
 53→            let pattern_parts: Vec<&str> = schema_key.split('/').collect();
 54→            if path_parts.len() != pattern_parts.len() + 1 {
 55→                continue;
 56→            }
 57→            if path_parts[0] != pattern_parts[0] {
 58→                continue;
 59→            }
 60→
 61→            let mut matched = true;
 62→            for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
 63→                if *pat_seg != "{id}" && path_seg != pat_seg {
 64→                    matched = false;
 65→                    break;
 66→                }
 67→            }
 68→
 69→            if matched {
 70→                return Some(schema);
 71→            }
 72→        }
 73→
 74→        None
 75→    }
 76→
 77→    #[instrument(skip(self, authority_permit, scribe, state), fields(page_id = %page_id, layer = %layer_name))]
 78→    async fn fanout_sync_meta_from_authority(
 79→        &self,
 80→        page_id: &str,
 81→        layer_name: &str,
 82→        authority_permit: &gurkha::Permit,
 83→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
 84→        state: &PeerActorState<C>,
 85→    ) {
 86→        let our_did = match state.butler.user_info().await {
 87→            Ok(info) => info.did,
 88→            Err(e) => {
 89→                warn!(error = %e, "Unable to resolve node DID for sync-meta fanout");
 90→                return;
 91→            }
 92→        };
 93→
 94→        let mut recipients = BTreeSet::new();
 95→        match authority_permit.authorized_peers() {
 96→            Ok(Some(explicit)) => {
 97→                for did in explicit {
 98→                    if did != our_did {
 99→                        recipients.insert(did);
100→                    }
101→                }
102→            }
103→            Ok(None) => {
104→                // Authority permit doesn't carry dynamic_layer_schemas — look up
105→                // the node's own page permit which has them.
106→                let our_page_permit = match state.butler.pages().get(page_id) {
107→                    Ok(Some(page)) => page.permit,
108→                    _ => None,
109→                };
110→                let parsed_page_permit = our_page_permit.as_deref().and_then(|t| gurkha::Permit::from_token(t).ok());
111→                let schema = parsed_page_permit.as_ref().and_then(|p| {
112→                    Self::authority_schema_for_layer(p, page_id, layer_name)
113→                });
114→                let Some(schema) = schema else {
115→                    warn!(page_id = %page_id, layer = %layer_name, "No matching dynamic schema in page permit for role fanout");
116→                    return;
117→                };
118→
119→                let all_users = match state.butler.store().list_authorized_users_for_page(page_id) {
120→                    Ok(users) => users,
121→                    Err(e) => {
122→                        warn!(error = %e, "Failed to list authorized users for role fanout");
123→                        return;
124→                    }
125→                };
126→
127→                for user_did in all_users {
128→                    if user_did == our_did {
129→                        continue;
130→                    }
131→
132→                    let permit_token = match state.butler.store().get_user_page_permit(page_id, &user_did) {
133→                        Ok(Some(p)) => p,
134→                        _ => continue,
135→                    };
136→
137→                    let parsed = match gurkha::Permit::from_token(&permit_token) {
138→                        Ok(p) => p,
139→                        Err(_) => continue,
140→                    };
141→
142→                    let role = parsed
143→                        .get_fact("role")
144→                        .and_then(|v| v.as_str())
145→                        .or_else(|| parsed.get_fact("relationship").and_then(|v| v.as_str()));
146→
147→                    if let Some(role) = role {
148→                        if schema.role_permissions.contains_key(role) {
149→                            recipients.insert(user_did);
150→                        }
151→                    }
152→                }
153→            }
154→            Err(e) => {
155→                warn!(error = %e, "Invalid authorized_peers in layer authority permit");
156→                return;
157→            }
158→        }
159→
160→        info!(page_id = %page_id, layer = %layer_name, count = recipients.len(), "Fanout sync-meta to recipients");
161→
162→        let bare_channel = layer_name
163→            .strip_prefix(&format!("{}/", page_id))
164→            .unwrap_or(layer_name);
165→
166→        for did in recipients {
167→            let sync_meta_layer = format!("__sync_meta/{}", did);
168→            let sync_meta_key = bare_channel.to_string();
169→            info!(page_id = %page_id, target = %did, sync_meta_layer = %sync_meta_layer, key = %sync_meta_key, "Writing sync-meta entry for recipient");
170→            if let Err(e) = scribe.cast(butler::ScribeMessage::MapInsert {
171→                layer_name: sync_meta_layer,
172→                path: String::new(),
173→                key: sync_meta_key.clone(),
174→                value: serde_json::json!({"synced": false, "version": 1}),
175→            }) {
176→                warn!(page_id = %page_id, layer = %layer_name, target = %did, error = %e, "Failed to write recipient sync-meta entry");
177→            }
178→
179→            // Authorize recipient on the channel layer so Scribe broadcasts reach them
180→            scribe.cast(butler::ScribeMessage::AuthorizeLayerSubscriber {
181→                layer_name: bare_channel.to_string(),
182→                subscriber_did: did.clone(),
183→            }).ok();
184→            info!(page_id = %page_id, target = %did, layer = %bare_channel, "Authorized recipient on channel layer for broadcast");
185→        }
186→    }
