188→    #[instrument(skip(self, state, scribe), fields(page_id = %page_id, sync_meta_layer = %sync_meta_layer))]
189→    async fn request_missing_layers_from_sync_meta(
190→        &self,
191→        page_id: &str,
192→        sync_meta_layer: &str,
193→        scribe: &ractor::ActorRef<butler::ScribeMessage>,
194→        state: &mut PeerActorState<C>,
195→    ) {
196→        let normalized_sync_meta_layer = sync_meta_layer
197→            .strip_prefix(&format!("{}/", page_id))
198→            .unwrap_or(sync_meta_layer)
199→            .to_string();
200→
201→        let (data_tx, data_rx) = tokio::sync::oneshot::channel();
202→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetLayerData {
203→            layer_name: normalized_sync_meta_layer,
204→            reply: data_tx,
205→        }) {
206→            warn!(error = %e, "Failed to read sync-meta layer for request planning");
207→            return;
208→        }
209→
210→        let sync_meta_json = match data_rx.await {
211→            Ok(Ok(v)) => v,
212→            Ok(Err(e)) => {
213→                warn!(error = %e, "GetLayerData failed for sync-meta layer");
214→                return;
215→            }
216→            Err(_) => {
217→                warn!("GetLayerData reply channel closed for sync-meta layer");
218→                return;
219→            }
220→        };
221→
222→        let Some(entries) = sync_meta_json.as_object() else {
223→            warn!("sync-meta layer content is not a map object");
224→            return;
225→        };
226→
227→        for (layer_name, _entry) in entries {
228→            let normalized_layer_name = layer_name
229→                .strip_prefix(&format!("{}/", page_id))
230→                .unwrap_or(layer_name)
231→                .to_string();
232→
233→            if normalized_layer_name.starts_with("__sync_meta/") {
234→                continue;
235→            }
236→
237→            let (exists_tx, exists_rx) = tokio::sync::oneshot::channel();
238→            if let Err(e) = scribe.cast(butler::ScribeMessage::LayerExists {
239→                layer_name: normalized_layer_name.clone(),
240→                reply: exists_tx,
241→            }) {
242→                warn!(layer = %normalized_layer_name, error = %e, "Failed to check layer existence");
243→                continue;
244→            }
245→
246→            let exists = match exists_rx.await {
247→                Ok(v) => v,
248→                Err(_) => {
249→                    warn!(layer = %normalized_layer_name, "LayerExists reply channel closed");
250→                    continue;
251→                }
252→            };
253→
254→            if exists {
255→                continue;
256→            }
257→
258→            info!(page_id = %page_id, layer = %normalized_layer_name, "Requesting missing layer via SyncReset after sync-meta discovery");
259→            let msg = Message::SyncReset(SyncResetMsg {
260→                page_id: page_id.to_string(),
261→                layer_name: normalized_layer_name,
262→            });
263→            self.send_message(&msg, state).await;
264→        }
265→    }
