267→    /// Handle incoming SyncOffer from peer (Step 1)
268→    ///
269→    /// **Context**: Peer has a layer update with their state vector
270→    /// **Peer sends**: SyncOffer with page_id, layer_name, encrypted data, state_vector
271→    /// **We decrypt**: ECDH with ephemeral_public + our encryption key
272→    /// **We apply**: Via Scribe.ApplyUpdateWithResult (handles merge)
273→    /// **We respond**: SyncAccept with our state vector after applying (only if successful)
274→    #[instrument(skip(self, myself, state, data, their_state_vector, ephemeral_public, authority_permit), fields(page_id = %page_id, layer_name = %layer_name))]
275→    pub(in crate::peer_actor) async fn on_sync_offer(
276→        &self,
277→        myself: ractor::ActorRef<super::super::PeerMessage>,
278→        page_id: &str,
279→        layer_name: &str,
280→        data: &[u8],
281→        their_state_vector: &[u8],
282→        ephemeral_public: &[u8; 32],
283→        authority_permit: Option<&str>,
284→        state: &mut PeerActorState<C>,
285→    ) {
286→        let (peer_did, _) = match require_auth(&state.state) {
287→            Ok(info) => (info.0.to_string(), info.1.to_string()),
288→            Err(_) => {
289→                warn!("SyncOffer from unauthenticated peer: {}", self.node_id);
290→                return;
291→            }
292→        };
293→
294→        let peer_device_id = self.node_id.to_string();
295→
296→        debug!(
297→            "SyncOffer: page={} layer={} ({} bytes, vector {} bytes) from {}",
298→            page_id, layer_name, data.len(), their_state_vector.len(), peer_did
299→        );
300→
301→        // Open page early so bundled authority fanout and apply share one Scribe handle.
302→        let scribe = match state.butler.open_page(page_id).await {
303→            Ok(s) => s,
304→            Err(e) => {
305→                error!("Failed to open page {}: {}", page_id, e);
306→                return;
307→            }
308→        };
309→
310→        if let Some(permit) = authority_permit {
311→            match gurkha::Permit::from_token(permit) {
312→                Ok(parsed) => {
313→                    if parsed.token_type() == Some("layer_authority") {
314→                        let audience = parsed.parsed().audience().to_string();
315→                        let version = parsed
316→                            .get_fact("version")
317→                            .and_then(|v| v.as_u64())
318→                            .unwrap_or(0);
319→                        let full_layer_name = if layer_name.starts_with(&format!("{}/", page_id)) {
320→                            layer_name.to_string()
321→                        } else {
322→                            format!("{}/{}", page_id, layer_name)
323→                        };
324→                        if let Err(e) = state.butler.permits().store_layer_authority_permit(
325→                            page_id,
326→                            &full_layer_name,
327→                            &audience,
328→                            version,
329→                            permit,
330→                        ) {
331→                            warn!(
332→                                page_id = %page_id,
333→                                layer = %full_layer_name,
334→                                audience = %audience,
335→                                error = %e,
336→                                "Failed to store bundled layer authority permit"
337→                            );
338→                        }
339→
340→                        if state.mode == crate::CourierMode::Node {
341→                            self
342→                                .fanout_sync_meta_from_authority(
343→                                    page_id,
344→                                    &full_layer_name,
345→                                    &parsed,
346→                                    &scribe,
347→                                    state,
348→                                )
349→                                .await;
350→                        }
351→                    }
352→                }
353→                Err(e) => {
354→                    warn!(page_id = %page_id, layer = %layer_name, error = %e, "Invalid bundled authority permit in SyncOffer");
355→                }
356→            }
357→        }
358→
359→        // Decrypt transit-encrypted update using ECDH
360→        let our_secret = match state.butler.encryption_key().await {
361→            Ok(key) => key,
362→            Err(e) => {
363→                error!("Failed to get encryption key for SyncOffer decryption: {}", e);
364→                return;
365→            }
366→        };
367→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
368→            Ok(data) => data,
369→            Err(e) => {
370→                error!("Failed to decrypt SyncOffer from {}: {}", peer_did, e);
371→                return;
372→            }
373→        };
374→
375→        // Auto-subscribe peer if not already subscribed (both Node and User modes)
376→        // For Node mode: Ensures can_write() can check viewer's write permissions
377→        // For User mode: Ensures node gets subscribed to viewer's scribe for bidirectional sync
378→        if !state.page_subscriptions.contains_key(page_id) {
379→            info!("Auto-subscribing peer {} to page {} from SyncOffer", peer_did, page_id);
380→            self.subscribe_to_page(myself.clone(), page_id, "", state).await;
381→        }
382→
383→        // Apply the update with result feedback
384→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
385→        if let Err(e) = scribe.cast(butler::ScribeMessage::ApplyUpdateWithResult {
386→            layer_name: layer_name.to_string(),
387→            update: decrypted_data,
388→            from_peer: Some((peer_did.clone(), peer_device_id.clone())),
389→            permit: None,
390→            reply: reply_tx,
391→        }) {
392→            error!("Failed to send ApplyUpdateWithResult to Scribe: {}", e);
393→            return;
394→        }
395→
396→        // Wait for apply result - only send SyncAccept if successful
397→        match reply_rx.await {
398→            Ok(Ok(())) => {
399→                debug!("ApplyUpdate succeeded for page={} layer={}", page_id, layer_name);
400→
401→                if Self::is_sync_meta_layer(page_id, layer_name) {
402→                    self
403→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
404→                        .await;
405→                }
406→            }
407→            Ok(Err(e)) => {
408→                warn!("ApplyUpdate rejected for page={} layer={}: {}", page_id, layer_name, e);
409→                // DO NOT send SyncAccept - this stops the infinite retry loop
410→                return;
411→            }
412→            Err(_) => {
413→                error!("ApplyUpdate reply channel closed for page={} layer={}", page_id, layer_name);
414→                return;
415→            }
416→        }
417→
418→        // Get our state vector after applying
419→        let (tx, rx) = tokio::sync::oneshot::channel();
420→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
421→            layer_name: layer_name.to_string(),
422→            reply: tx.into(),
423→        }) {
424→            error!("Failed to request state vector from Scribe: {}", e);
425→            return;
426→        }
427→
428→        let our_state_vector = match rx.await {
429→            Ok(Ok(vector)) => vector,
430→            Ok(Err(e)) => {
431→                error!("Scribe returned error getting state vector: {}", e);
432→                return;
433→            }
434→            Err(_) => {
435→                error!("Scribe dropped state vector reply channel");
436→                return;
437→            }
438→        };
439→
440→        // Send SyncAccept with our state vector
441→        let msg = Message::SyncAccept(SyncAcceptMsg {
442→            page_id: page_id.to_string(),
443→            layer_name: layer_name.to_string(),
444→            state_vector: our_state_vector.clone(),
445→        });
446→
447→        self.send_message(&msg, state).await;
448→        debug!(
449→            "Sent SyncAccept for page={} layer={} to {} (our vector {} bytes)",
450→            page_id, layer_name, peer_did, our_state_vector.len()
451→        );
452→    }
453→
454→    /// Handle incoming SyncAccept from peer (Step 2)
455→    ///
456→    /// **Context**: Peer applied our update and reports their state vector
457→    /// **Peer sends**: SyncAccept with their state vector after applying
458→    /// **We compare**: Their vector with our current vector
459→    /// **If match**: Send SyncAck (sync complete)
460→    /// **If diverged**: Send new SyncOffer with full diff from their vector (resync)
461→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
462→    pub(in crate::peer_actor) async fn on_sync_accept(
463→        &self,
464→        page_id: &str,
465→        layer_name: &str,
466→        their_state_vector: &[u8],
467→        state: &mut PeerActorState<C>,
468→    ) {
469→        let (peer_did, _) = match require_auth(&state.state) {
470→            Ok(info) => (info.0.to_string(), info.1.to_string()),
471→            Err(_) => {
472→                warn!("SyncAccept from unauthenticated peer: {}", self.node_id);
473→                return;
474→            }
475→        };
476→
477→        debug!(
478→            "SyncAccept: page={} layer={} from {} (their vector {} bytes)",
479→            page_id, layer_name, peer_did, their_state_vector.len()
480→        );
481→
482→        // Get pending sync context (may not exist for fire-and-forget broadcasts)
483→        let key = (page_id.to_string(), layer_name.to_string());
484→        let pending = state.pending_sync_offers.remove(&key);
485→
486→        // Get our current state vector from Scribe
487→        let scribe = match state.butler.open_page(page_id).await {
488→            Ok(s) => s,
489→            Err(e) => {
490→                error!("Failed to open page {}: {}", page_id, e);
491→                return;
492→            }
493→        };
494→
495→        let (tx, rx) = tokio::sync::oneshot::channel();
496→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
497→            layer_name: layer_name.to_string(),
498→            reply: tx.into(),
499→        }) {
500→            error!("Failed to request state vector from Scribe: {}", e);
501→            return;
502→        }
503→
504→        let our_current_vector = match rx.await {
505→            Ok(Ok(vector)) => vector,
506→            Ok(Err(e)) => {
507→                error!("Scribe returned error getting state vector: {}", e);
508→                return;
509→            }
510→            Err(_) => {
511→                error!("Scribe dropped state vector reply channel");
512→                return;
513→            }
514→        };
515→
516→        // Handle based on whether we have a pending offer
517→        match pending {
518→            None => {
519→                // Fire-and-forget broadcast: No pending offer tracked.
520→                // Just update peer vector cache and send SyncAck. Trust CRDT to converge.
521→                debug!(
522→                    "SyncAccept: no pending offer (fire-and-forget) for page={} layer={} - sending SyncAck",
523→                    page_id, layer_name
524→                );
525→
526→                let msg = Message::SyncAck(SyncAckMsg {
527→                    page_id: page_id.to_string(),
528→                    layer_name: layer_name.to_string(),
529→                    state_vector: our_current_vector,
530→                });
531→                self.send_message(&msg, state).await;
532→
533→                // Update Scribe's in-memory vector cache (persistence via periodic flush)
534→                let peer_device_id = self.node_id.to_string();
535→                if let Some(subscription) = state.page_subscriptions.get(page_id) {
536→                    let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
537→                        user_did: peer_did,
538→                        device_id: peer_device_id,
539→                        layer_name: layer_name.to_string(),
540→                        state_vector: their_state_vector.to_vec(),
541→                    });
542→                }
543→            }
544→            Some(offer) => {
545→                // Tracked sync (initial sync / reconciliation): Compare vectors
546→                trace!(
547→                    "SyncAccept comparison: their_vector={} bytes, offered_vector={} bytes, current_vector={} bytes",
548→                    their_state_vector.len(),
549→                    offer.our_state_vector.len(),
550→                    our_current_vector.len()
551→                );
552→
553→                if their_state_vector == offer.our_state_vector.as_slice() {
554→                    // In sync! Send SyncAck
555→                    trace!(
556→                        "SyncAccept: vectors match for page={} layer={} - sending SyncAck",
557→                        page_id, layer_name
558→                    );
559→
560→                    let msg = Message::SyncAck(SyncAckMsg {
561→                        page_id: page_id.to_string(),
562→                        layer_name: layer_name.to_string(),
563→                        state_vector: our_current_vector,
564→                    });
565→                    self.send_message(&msg, state).await;
566→
567→                    // Update Scribe's in-memory vector cache (persistence via periodic flush)
568→                    let peer_device_id = self.node_id.to_string();
569→                    if let Some(subscription) = state.page_subscriptions.get(page_id) {
570→                        let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
571→                            user_did: peer_did,
572→                            device_id: peer_device_id,
573→                            layer_name: layer_name.to_string(),
574→                            state_vector: their_state_vector.to_vec(),
575→                        });
576→                    }
577→                } else {
578→                    // Diverged! Check if we should resync or fall back to SyncReset
579→                    let new_attempts = offer.resync_attempts + 1;
580→
581→                    if new_attempts > MAX_RESYNC_ATTEMPTS {
582→                        // Max resyncs exceeded - fall back to SyncReset (request full snapshot)
583→                        warn!(
584→                            "SyncAccept: max resyncs ({}) exceeded for page={} layer={} - sending SyncReset",
585→                            MAX_RESYNC_ATTEMPTS, page_id, layer_name
586→                        );
587→
588→                        let msg = Message::SyncReset(SyncResetMsg {
589→                            page_id: page_id.to_string(),
590→                            layer_name: layer_name.to_string(),
591→                        });
592→                        self.send_message(&msg, state).await;
593→                        return;
594→                    }
595→
596→                    // Still have retries - send resync SyncOffer with full diff from their vector
597→                    info!(
598→                        "SyncAccept: vectors DIVERGED for page={} layer={} - sending resync SyncOffer (attempt {}/{})",
599→                        page_id, layer_name, new_attempts, MAX_RESYNC_ATTEMPTS
600→                    );
601→
602→                    // Get diff from their state vector
603→                    let (tx, rx) = tokio::sync::oneshot::channel();
604→                    if let Err(e) = scribe.cast(butler::ScribeMessage::GetUpdatesSince {
605→                        layer_name: layer_name.to_string(),
606→                        state_vector: their_state_vector.to_vec(),
607→                        reply: tx,
608→                    }) {
609→                        error!("Failed to request updates from Scribe: {}", e);
610→                        return;
611→                    }
612→
613→                    let diff = match rx.await {
614→                        Ok(Ok(d)) => d,
615→                        Ok(Err(e)) => {
616→                            error!("Scribe returned error getting updates: {}", e);
617→                            return;
618→                        }
619→                        Err(_) => {
620→                            error!("Scribe dropped updates reply channel");
621→                            return;
622→                        }
623→                    };
624→
625→                    // Encrypt and send new SyncOffer
626→                    let peer_encryption_key = match state.peer_encryption_key {
627→                        Some(key) => key,
628→                        None => {
629→                            warn!("Cannot send resync SyncOffer: peer encryption key not set");
630→                            return;
631→                        }
632→                    };
633→
634→                    let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
635→                        &peer_encryption_key,
636→                        &diff,
637→                    ) {
638→                        Ok(result) => result,
639→                        Err(e) => {
640→                            error!("Failed to encrypt resync data: {}", e);
641→                            return;
642→                        }
643→                    };
644→
645→                    // Track this new pending sync with incremented attempt counter
646→                    state.pending_sync_offers.insert(
647→                        key,
648→                        super::super::PendingSyncOffer {
649→                            our_state_vector: our_current_vector.clone(),
650→                            permit: String::new(),
651→                            resync_attempts: new_attempts,
652→                        },
653→                    );
654→
655→                    let layer_name_owned = layer_name.to_string();
656→                    let msg = Message::SyncOffer(SyncOfferMsg {
657→                        page_id: page_id.to_string(),
658→                        layer_type: LayerType::from_layer_name(&layer_name_owned),
659→                        layer_name: layer_name_owned,
660→                        data: encrypted_data,
661→                        state_vector: our_current_vector,
662→                        ephemeral_public,
663→                        authority_permit: None,
664→                    });
665→                    self.send_message(&msg, state).await;
666→                }
667→            }
668→        }
669→    }
