671→    /// Handle incoming SyncAck from peer (Step 3)
672→    ///
673→    /// **Context**: Peer confirms sync complete after comparing vectors
674→    /// **Peer sends**: SyncAck with their final state vector
675→    /// **We do**: Update cached peer vector, log sync complete
676→    #[instrument(skip(self, state, their_state_vector), fields(page_id = %page_id, layer_name = %layer_name))]
677→    pub(in crate::peer_actor) async fn on_sync_ack(
678→        &self,
679→        page_id: &str,
680→        layer_name: &str,
681→        their_state_vector: &[u8],
682→        state: &mut PeerActorState<C>,
683→    ) {
684→        let (peer_did, _) = match require_auth(&state.state) {
685→            Ok(info) => (info.0.to_string(), info.1.to_string()),
686→            Err(_) => {
687→                warn!("SyncAck from unauthenticated peer: {}", self.node_id);
688→                return;
689→            }
690→        };
691→
692→        debug!(
693→            "SyncAck: page={} layer={} from {} - sync complete",
694→            page_id, layer_name, peer_did
695→        );
696→
697→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
698→        let peer_device_id = self.node_id.to_string();
699→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
700→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
701→                user_did: peer_did.clone(),
702→                device_id: peer_device_id.clone(),
703→                layer_name: layer_name.to_string(),
704→                state_vector: their_state_vector.to_vec(),
705→            });
706→        }
707→
708→        // Clean up any pending sync for this page/layer (shouldn't exist but be safe)
709→        let key = (page_id.to_string(), layer_name.to_string());
710→        state.pending_sync_offers.remove(&key);
711→
712→        // Check if this is an assets layer sync - trigger asset fetch for missing blobs
713→        if layer_name == "assets" || layer_name.ends_with("/assets") {
714→            self.trigger_asset_sync_after_layer_sync(page_id, layer_name, state).await;
715→        }
