718→    /// Handle incoming SyncReset from peer (fallback after max resyncs)
719→    ///
720→    /// **Context**: Peer exceeded MAX_RESYNC_ATTEMPTS OR explicitly needs layer snapshot.
721→    /// **Both modes**: Respond with SyncSnapshot when layer exists locally.
722→    #[instrument(skip(self, state), fields(page_id = %page_id, layer_name = %layer_name))]
723→    pub(in crate::peer_actor) async fn on_sync_reset(
724→        &self,
725→        page_id: &str,
726→        layer_name: &str,
727→        state: &mut PeerActorState<C>,
728→    ) {
729→        let peer_did = match require_auth(&state.state) {
730→            Ok((did, _)) => did.to_string(),
731→            Err(_) => {
732→                warn!("SyncReset from unauthenticated peer: {}", self.node_id);
733→                return;
734→            }
735→        };
736→
737→        info!(
738→            "SyncReset: page={} layer={} from {} - sending full snapshot",
739→            page_id, layer_name, peer_did
740→        );
741→
742→        // Get Scribe and export full snapshot
743→        let scribe = match state.butler.open_page(page_id).await {
744→            Ok(s) => s,
745→            Err(e) => {
746→                error!("Failed to open page {} for SyncReset: {}", page_id, e);
747→                return;
748→            }
749→        };
750→
751→        // Get full snapshot
752→        let (snapshot_tx, snapshot_rx) = tokio::sync::oneshot::channel();
753→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetSnapshot {
754→            layer_name: layer_name.to_string(),
755→            reply: snapshot_tx,
756→        }) {
757→            error!("Failed to request snapshot from Scribe: {}", e);
758→            return;
759→        }
760→
761→        let snapshot = match snapshot_rx.await {
762→            Ok(Some(data)) => data,
763→            Ok(None) => {
764→                warn!("Layer {} not found in Scribe for SyncReset", layer_name);
765→                return;
766→            }
767→            Err(_) => {
768→                error!("Scribe dropped snapshot reply channel");
769→                return;
770→            }
771→        };
772→
773→        // Get state vector
774→        let (vector_tx, vector_rx) = tokio::sync::oneshot::channel();
775→        if let Err(e) = scribe.cast(butler::ScribeMessage::GetStateVector {
776→            layer_name: layer_name.to_string(),
777→            reply: vector_tx.into(),
778→        }) {
779→            error!("Failed to request state vector from Scribe: {}", e);
780→            return;
781→        }
782→
783→        let state_vector = match vector_rx.await {
784→            Ok(Ok(v)) => v,
785→            Ok(Err(e)) => {
786→                error!("Scribe returned error getting state vector: {}", e);
787→                return;
788→            }
789→            Err(_) => {
790→                error!("Scribe dropped state vector reply channel");
791→                return;
792→            }
793→        };
794→
795→        // Encrypt snapshot for transfer
796→        let peer_encryption_key = match state.peer_encryption_key {
797→            Some(key) => key,
798→            None => {
799→                warn!("Cannot send SyncSnapshot: peer encryption key not set");
800→                return;
801→            }
802→        };
803→
804→        let (ephemeral_public, encrypted_snapshot) = match herald::encrypt_for_transfer(
805→            &peer_encryption_key,
806→            &snapshot,
807→        ) {
808→            Ok(result) => result,
809→            Err(e) => {
810→                error!("Failed to encrypt snapshot: {}", e);
811→                return;
812→            }
813→        };
814→
815→        // Send SyncSnapshot
816→        let layer_name_owned = layer_name.to_string();
817→        let msg = Message::SyncSnapshot(SyncSnapshotMsg {
818→            page_id: page_id.to_string(),
819→            layer_type: LayerType::from_layer_name(&layer_name_owned),
820→            layer_name: layer_name_owned,
821→            snapshot: encrypted_snapshot,
822→            state_vector,
823→            ephemeral_public,
824→        });
825→        self.send_message(&msg, state).await;
826→
827→        info!(
828→            "Sent SyncSnapshot for page={} layer={} to {} ({} bytes)",
829→            page_id, layer_name, peer_did, snapshot.len()
830→        );
831→    }
