833→    /// Handle incoming SyncSnapshot from peer (response to SyncReset)
834→    ///
835→    /// **Context**: Peer responded to our SyncReset with a full snapshot.
836→    /// **Both modes**: Replace local layer with received state.
837→    #[instrument(skip(self, state, snapshot, their_state_vector, ephemeral_public), fields(page_id = %page_id, layer_name = %layer_name))]
838→    pub(in crate::peer_actor) async fn on_sync_snapshot(
839→        &self,
840→        page_id: &str,
841→        layer_name: &str,
842→        snapshot: &[u8],
843→        their_state_vector: &[u8],
844→        ephemeral_public: &[u8; 32],
845→        state: &mut PeerActorState<C>,
846→    ) {
847→        let peer_did = match require_auth(&state.state) {
848→            Ok((did, _)) => did.to_string(),
849→            Err(_) => {
850→                warn!("SyncSnapshot from unauthenticated peer: {}", self.node_id);
851→                return;
852→            }
853→        };
854→
855→        info!(
856→            "SyncSnapshot: page={} layer={} from {} ({} bytes) - replacing local state",
857→            page_id, layer_name, peer_did, snapshot.len()
858→        );
859→
860→        // Decrypt snapshot
861→        let our_secret = match state.butler.encryption_key().await {
862→            Ok(key) => key,
863→            Err(e) => {
864→                error!("Failed to get encryption key for SyncSnapshot decryption: {}", e);
865→                return;
866→            }
867→        };
868→
869→        let decrypted_snapshot = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, snapshot) {
870→            Ok(data) => data,
871→            Err(e) => {
872→                error!("Failed to decrypt SyncSnapshot from {}: {}", peer_did, e);
873→                return;
874→            }
875→        };
876→
877→        // Get Scribe and replace layer
878→        let scribe = match state.butler.open_page(page_id).await {
879→            Ok(s) => s,
880→            Err(e) => {
881→                error!("Failed to open page {} for SyncSnapshot: {}", page_id, e);
882→                return;
883→            }
884→        };
885→
886→        // Replace layer with snapshot
887→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
888→        if let Err(e) = scribe.cast(butler::ScribeMessage::ReplaceLayer {
889→            layer_name: layer_name.to_string(),
890→            snapshot: decrypted_snapshot,
891→            reply: reply_tx,
892→        }) {
893→            error!("Failed to send ReplaceLayer to Scribe: {}", e);
894→            return;
895→        }
896→
897→        match reply_rx.await {
898→            Ok(Ok(())) => {
899→                info!(
900→                    "SyncSnapshot applied: page={} layer={} - sync recovery complete",
901→                    page_id, layer_name
902→                );
903→
904→                if Self::is_sync_meta_layer(page_id, layer_name) {
905→                    self
906→                        .request_missing_layers_from_sync_meta(page_id, layer_name, &scribe, state)
907→                        .await;
908→                }
909→            }
910→            Ok(Err(e)) => {
911→                error!("ReplaceLayer failed for page={} layer={}: {}", page_id, layer_name, e);
912→                return;
913→            }
914→            Err(_) => {
915→                error!("Scribe dropped ReplaceLayer reply channel");
916→                return;
917→            }
918→        }
919→
920→        // Update Scribe's in-memory vector cache (persistence via periodic flush)
921→        let peer_device_id = self.node_id.to_string();
922→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
923→            let _ = subscription.scribe.cast(butler::ScribeMessage::UpdatePeerVector {
924→                user_did: peer_did.clone(),
925→                device_id: peer_device_id,
926→                layer_name: layer_name.to_string(),
927→                state_vector: their_state_vector.to_vec(),
928→            });
929→        }
930→
931→        // Clean up any pending sync
932→        let key = (page_id.to_string(), layer_name.to_string());
933→        state.pending_sync_offers.remove(&key);
934→    }
935→}
