332→/// Create a new layer from peer sync
333→///
334→/// **Context**: Peer sent update for a layer we don't have yet
335→/// **We do**: Create layer, set up observer, notify UI
336→#[instrument(skip(state), fields(page_id = %state.page_id))]
337→fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
338→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
339→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
340→    let layer_name = layer_name.as_str();
341→    let mut unit = LayerUnit::new_empty();
342→    unit.set_local_only(!state.should_sync_layer(layer_name));
343→    unit.mark_dirty();
344→    state.units.insert(layer_name.to_string(), unit);
345→    info!(layer = %layer_name, "Created new layer from peer sync");
346→
347→    // Authorize existing subscribers for this new layer
348→    if let Ok(subs) = state.subscribers.read() {
349→        for ((did, _), info) in subs.iter() {
350→            if info.can_receive_layer(layer_name, &state.page_id) {
351→                if let Some(unit) = state.units.get(layer_name) {
352→                    unit.authorize_did(did);
353→                    state.emit_layer_auth_capture(layer_name, did, "authorized_subscriber");
354→                }
355→            }
356→        }
357→    }
358→
359→    // Apply any pending authorizations (from AuthorizeLayerSubscriber before layer creation)
360→    if let Some(pending_dids) = state.pending_layer_authorizations.remove(layer_name) {
361→        if let Some(unit) = state.units.get(layer_name) {
362→            for did in &pending_dids {
363→                unit.authorize_did(did);
364→                state.emit_layer_auth_capture(layer_name, did, "applied_pending");
365→                info!(layer = %layer_name, did = %did, "Applied pending layer authorization");
366→            }
367→        }
368→    }
369→
370→    // Set up Loro observer for new layer to enable sync broadcasts
371→    setup_layer_observer(state, layer_name);
372→
373→    // Notify UI subscribers about the new layer
374→    notify_layer_discovered(state, layer_name);
375→}
