377→/// Apply CRDT update to layer
378→///
379→/// **Context**: Actually merge the update into the layer
380→/// **We do**: Set pending source, apply, clear pending source
381→#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
382→fn apply_crdt_update(
383→    state: &mut ScribeState,
384→    layer_name: &str,
385→    update: &[u8],
386→    from_peer: Option<(String, String)>,
387→) -> Result<(), String> {
388→    // Set pending update source BEFORE apply() so observer knows who caused this change
389→    set_pending_update_source(state, from_peer);
390→
391→    // Get the layer and apply update
392→    let result = if let Some(unit) = state.units.get(layer_name) {
393→        unit.layer().apply(update)
394→    } else {
395→        clear_pending_update_source(state);
396→        return Err("Layer not found".to_string());
397→    };
398→
399→    if let Err(e) = result {
400→        // Clear on error too
401→        clear_pending_update_source(state);
402→        error!(error = %e, "Failed to apply update to layer");
403→        return Err(format!("Failed to apply update: {}", e));
404→    }
405→
406→    // Clear pending update source AFTER apply() (observer already captured it)
407→    clear_pending_update_source(state);
408→
409→    Ok(())
410→}
