278→/// Find matching dynamic schema for a layer received from a peer
279→///
280→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
281→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
282→pub fn find_matching_dynamic_schema<'a>(
283→    permit: &'a gurkha::Permit,
284→    layer_name: &str,
285→    page_id: &str,
286→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
287→    let schemas = permit.dynamic_layer_schemas();
288→    if schemas.is_empty() {
289→        return None;
290→    }
291→
292→    // Strip page_id prefix to get bare layer path
293→    let page_prefix = format!("{}/", page_id);
294→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
295→
296→    let path_parts: Vec<&str> = bare_path.split('/').collect();
297→
298→    // Path must have at least 3 segments: prefix/did/id[/suffix]
299→    if path_parts.len() < 3 {
300→        return None;
301→    }
302→
303→    // Second segment should be a DID (the creator)
304→    let potential_creator = path_parts[1];
305→    if !potential_creator.starts_with("did:") {
306→        return None;
307→    }
308→
309→    // Try each schema pattern
310→    for (schema_key, schema) in schemas {
311→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
312→
313→        // Dynamic path has one extra segment (DID) compared to pattern
314→        if path_parts.len() != pattern_parts.len() + 1 {
315→            continue;
316→        }
317→
318→        // First segment must match literally
319→        if path_parts[0] != pattern_parts[0] {
320→            continue;
321→        }
322→
323→        // path[2..] must match pattern[1..] (with {id} as wildcard)
324→        let mut matched = true;
325→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
326→            if *pat_seg != "{id}" && path_seg != pat_seg {
327→                matched = false;
328→                break;
329→            }
330→        }
331→
332→        if matched {
333→            return Some((schema_key, schema, potential_creator.to_string()));
334→        }
335→    }
336→
337→    None
338→}
