340→/// Validate that a layer path created by a peer matches their DID (namespace security)
341→///
342→/// **Context**: Node receives a new layer from a peer. Before accepting, verify
343→/// that the creator's DID is in the layer path (prevents namespace forgery).
344→///
345→/// **Returns**: true if the layer path contains the sender's DID
346→pub fn validate_creator_namespace(layer_name: &str, page_id: &str, sender_did: &str) -> bool {
347→    let page_prefix = format!("{}/", page_id);
348→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
349→
350→    // The creator's DID must be the second segment in the path
351→    let parts: Vec<&str> = bare_path.split('/').collect();
352→    if parts.len() < 2 {
353→        return false;
354→    }
355→
356→    parts[1] == sender_did
357→}
