 221→    ) -> std::result::Result<(), ActorProcessingErr> {
 222→        match message {
 223→            ScribeMessage::Subscribe {
 224→                user_did,
 225→                device_id,
 226→                broadcast_tx,
 227→                ephemeral_tx,
 228→                permit,
 229→            } => {
