 238→                // Send PeerSubscribed for all currently subscribed peers
 239→                // (peers that subscribed before this app opened)
 240→                if let Ok(subs) = state.subscribers.read() {
 241→                    info!(page_id = %state.page_id, peer_count = subs.len(), "Sending existing peers as PeerSubscribed");
 242→                    for ((user_did, _device_id), _info) in subs.iter() {
 243→                        let _ = tx.try_send(message::PageUpdate::PeerSubscribed {
 244→                            did: user_did.clone(),
 245→                            username: None,
 246→                        });
 247→                    }
 248→                }
 249→
 250→                // Presence state is delivered via CRDT sync (presence layer snapshot)
 251→                // No need to send OnlinePeers event — apps read from LayerChanged on {page_id}/presence
 252→
 253→                if let Ok(mut subs) = state.page_update_subscribers.write() {
 254→                    subs.push(tx);
 255→                    info!(page_id = %state.page_id, subscriber_count = subs.len(), "PageUpdate subscriber added");
 256→                }
 257→            }
 258→
 259→            ScribeMessage::ApplyUpdate {
 260→                layer_name,
 261→                update,
 262→                from_peer,
 263→                permit,
 264→            } => {
 265→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 266→                // Loro observer handles broadcast automatically after import()
 267→                let _ = sync::handle_apply_update(
 268→                    state,
 269→                    &layer_name,
 270→                    &update,
 271→                    from_peer,
 272→                    permit.as_deref(),
 273→                )
 274→                .await;
 275→            }
 276→
 277→            ScribeMessage::ApplyUpdateWithResult {
 278→                layer_name,
 279→                update,
 280→                from_peer,
 281→                permit,
 282→                reply,
 283→            } => {
 284→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 285→                // Loro observer handles broadcast automatically after import()
 286→                let result = sync::handle_apply_update(
 287→                    state,
 288→                    &layer_name,
 289→                    &update,
 290→                    from_peer,
 291→                    permit.as_deref(),
 292→                )
 293→                .await;
 294→                let _ = reply.send(result);
 295→            }
