 783→                let ephemeral_funcs = state.our_permit
 784→                    .as_ref()
 785→                    .map(|p| p.ephemeral_funcs().to_vec())
 786→                    .unwrap_or_default();
 787→                debug!(
 788→                    page_id = %state.page_id,
