479→/// Handle RemoveLayerAccess message
480→///
481→/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
482→/// **We do**: Validate capability, reject metadata-era revoke path
483→pub fn handle_remove_layer_access(
484→    state: &ScribeState,
485→    layer_name: &str,
486→    did: &str,
487→) -> Result<(), String> {
488→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
489→    if !permit.can_manage_layer_access() {
490→        return Err("No manage_layer_access capability".into());
491→    }
492→
493→    let _ = layer_name;
494→    let _ = did;
495→    Err("RemoveLayerAccess is deprecated; rotate/revoke layer authority permits instead".to_string())
496→}
