  1→//! Typed CRDT operation handlers
  2→//!
  3→//! Handles list, map, and counter operations for Scribe actor.
  4→//! **Broadcast**: Handled automatically by Loro observer after commit()
  5→//!
  6→//! **Path convention**:
  7→//! - Empty path ("") = use layer_name as container name directly (Lua bindings)
  8→//! - Non-empty path = use root map pattern with nested containers (template actions)
  9→
 10→use tracing::{debug, info, instrument};
 11→
 12→use crate::{ScribeError, Result};
 13→use domains::json_to_loro_value;
 14→
 15→use crate::layer_unit::LayerUnit;
 16→use crate::state::ScribeState;
 17→use crate::loro_observer;
 18→
 19→// Typed CRDT Operation Handlers
 20→
 21→/// Helper to ensure a layer exists, returns true if layer was newly created
 22→fn ensure_layer_exists(state: &mut ScribeState, layer_name: &str) -> bool {
 23→    let is_new = !state.units.contains_key(layer_name);
 24→    if is_new {
 25→        let mut unit = LayerUnit::new_empty();
 26→        unit.set_local_only(!state.should_sync_layer(layer_name));
 27→        state.units.insert(layer_name.to_string(), unit);
 28→        state.track_new_sync_layer_in_meta(layer_name);
 29→        debug!(layer = %layer_name, "Created new layer");
 30→    }
 31→
 32→    // Auto-authorize target DID on __sync_meta/{did} layers so node-side
 33→    // writes (e.g. fanout) can broadcast to the intended recipient.
 34→    if let Some(target_did) = layer_name.strip_prefix("__sync_meta/") {
 35→        if let Some(unit) = state.units.get(layer_name) {
 36→            unit.authorize_did(target_did);
 37→        }
 38→    }
 39→
 40→    is_new
 41→}
 42→
