 69→// Sync Target Resolution
 70→
 71→/// Get user_dids that should receive updates for this page.
 72→///
 73→/// **Context**: Called during broadcast to find unsubscribed targets.
 74→/// **Returns**: Vec<String> of user_dids - Coordinator handles device resolution.
 75→#[instrument(skip(state), fields(page_id = %state.page_id))]
 76→pub fn get_sync_targets(state: &ScribeState) -> Vec<String> {
 77→    match state.sync_config.as_ref().map(|c| c.mode) {
 78→        Some(SyncMode::ToSource) => {
 79→            // User mode: single target (the node's DID)
 80→            state.sync_config.as_ref()
 81→                .and_then(|c| c.sync_target.as_ref())
 82→                .map(|node_did| vec![node_did.clone()])
 83→                .unwrap_or_default()
 84→        }
 85→        Some(SyncMode::Broadcast) | None => {
 86→            // Node mode: query storage for authorized user_dids
 87→            state.peer_resolver
 88→                .as_ref()
 89→                .map(|r| r.list_authorized_users())
 90→                .unwrap_or_default()
 91→        }
 92→    }
 93→}
