442→/// Update sender's peer vector after receiving their update
443→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
444→fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
445→    if let Some(unit) = state.units.get(layer_name) {
446→        if let Ok(mut subs) = state.subscribers.write() {
