 13→
 14→/// Handle CreateDynamicLayer message
 15→///
 16→/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
 17→/// **We do**: Validate schema exists in permit, generate full path with our DID, create layer
 18→/// **Returns**: Full layer name (bare, without page_id prefix)
 19→pub fn handle_create_dynamic_layer(
 20→    state: &mut ScribeState,
 21→    schema_key: &str,
 22→    layer_id: &str,
 23→) -> Result<String, String> {
 24→    let permit = state.our_permit.as_ref()
 25→        .ok_or_else(|| "No permit available".to_string())?;
 26→
 27→    // Validate schema exists in our permit's dynamic_layer_schemas
 28→    let schemas = permit.dynamic_layer_schemas();
 29→    let schema = schemas
 30→        .get(schema_key)
 31→        .cloned()
 32→        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;
 33→
 34→    // Generate full layer path with our DID
 35→    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
 36→    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
 37→    let full_name = format!("{}/{}", state.page_id, bare_path);
 38→
 39→    // Check if layer already exists
 40→    if state.units.contains_key(&bare_path) {
 41→        info!(layer = %bare_path, "Dynamic layer already exists");
 42→        return Ok(full_name);
 43→    }
 44→
 45→    // Create the layer
 46→    info!(
 47→        page_id = %state.page_id,
 48→        schema = %schema_key,
 49→        layer = %bare_path,
 50→        "Creating dynamic layer"
 51→    );
 52→    let mut unit = LayerUnit::new_empty();
 53→    unit.set_local_only(!state.should_sync_layer(&bare_path));
 54→    unit.is_dynamic = true;
 55→    state.units.insert(bare_path.clone(), unit);
 56→    state.track_new_sync_layer_in_meta(&bare_path);
 57→
 58→    // Creator can sync — authorize all current subscribers (viewer mode: just the node)
 59→    if let Ok(subs) = state.subscribers.read() {
 60→        for ((did, _), _) in subs.iter() {
 61→            if let Some(unit) = state.units.get(&bare_path) {
 62→                unit.authorize_did(did);
 63→                state.emit_layer_auth_capture(&bare_path, did, "authorized_on_create");
 64→            }
 65→        }
 66→    }
 67→
 68→    // Set up observer for the new layer
 69→    loro_observer::setup_layer_observer(state, &bare_path);
 70→
 71→    issue_creator_layer_authority_permits(state, &full_name, &schema);
 72→
 73→    Ok(full_name)
 74→}
 75→
 76→fn issue_creator_layer_authority_permits(
 77→    state: &ScribeState,
 78→    full_layer_name: &str,
 79→    schema: &gurkha::DynamicLayerSchema,
 80→) {
 81→    let Some(ref issuer) = state.permit_issuer else { return; };
 82→
 83→    let mut targets: Vec<(String, Option<String>)> = Vec::new();
 84→    if let Ok(subs) = state.subscribers.read() {
 85→        for ((did, _device), info) in subs.iter() {
 86→            let role = info
 87→                .permit
 88→                .get_fact("role")
 89→                .and_then(|v| v.as_str())
 90→                .map(|r| r.to_string())
 91→                .or_else(|| {
 92→                    info.permit
 93→                        .get_fact("relationship")
 94→                        .and_then(|v| v.as_str())
 95→                        .map(|r| r.to_string())
 96→                });
 97→            targets.push((did.clone(), role));
 98→        }
 99→    }
100→
101→    for (audience, role) in targets {
102→        let Some(config) = authority_config_from_template(schema, role.as_deref()) else {
103→            warn!(
104→                page_id = %state.page_id,
105→                layer = %full_layer_name,
106→                audience = %audience,
107→                role = role.as_deref().unwrap_or("unknown"),
108→                "Skipping layer authority issuance: no matching template config"
109→            );
110→            continue;
111→        };
112→
113→        match issuer.issue_layer_authority_permit(
114→            &audience,
115→            full_layer_name,
116→            config,
117→            None,
118→            1,
119→        ) {
120→            Ok((_token, _cid)) => {
121→                info!(
122→                    page_id = %state.page_id,
123→                    layer = %full_layer_name,
124→                    audience = %audience,
125→                    "Issued creator layer authority permit"
126→                );
127→            }
128→            Err(e) => {
129→                warn!(
130→                    page_id = %state.page_id,
131→                    layer = %full_layer_name,
132→                    audience = %audience,
133→                    error = %e,
134→                    "Failed to issue creator layer authority permit"
135→                );
136→            }
137→        }
138→    }
139→}
140→
141→fn authority_config_from_template(
142→    schema: &gurkha::DynamicLayerSchema,
143→    role: Option<&str>,
144→) -> Option<gurkha::LayerConfig> {
145→    let mut config = match schema.grant {
146→        gurkha::GrantType::Explicit => schema.permissions.clone(),
147→        gurkha::GrantType::Role => role.and_then(|r| schema.role_permissions.get(r).cloned()),
148→    }?;
149→
150→    if config.layer_type.is_none() && !schema.layer_type.is_empty() {
151→        config.layer_type = Some(schema.layer_type.clone());
152→    }
153→
154→    Some(config)
155→}
156→
157→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
158→///
159→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
160→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
161→///
162→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
163→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
164→    let parts: Vec<&str> = schema_key.split('/').collect();
165→    let mut result = Vec::new();
166→
167→    if parts.is_empty() {
168→        return format!("{}/{}", our_did, layer_id);
169→    }
170→
171→    // First segment: literal
172→    result.push(parts[0].to_string());
173→
174→    // Insert our DID as the second segment (namespace)
175→    result.push(our_did.to_string());
176→
177→    // Remaining segments: replace {id} with layer_id, keep literals
178→    for part in &parts[1..] {
179→        if *part == "{id}" {
180→            result.push(layer_id.to_string());
181→        } else {
182→            result.push(part.to_string());
183→        }
184→    }
185→
186→    result.join("/")
187→}
188→
189→/// Determine recipients and create layer permits for a new dynamic layer
190→///
191→/// **Context**: Called by Scribe when detecting a new dynamic layer from a peer.
192→/// **Returns**: Ready-to-send permits — courier just distributes them.
193→/// **Uses**: PermitIssuer trait (context-aware gurkha) — never touches signing keys.
194→pub fn prepare_layer_permits(
195→    permit_issuer: &dyn PermitIssuer,
196→    page_id: &str,
197→    layer_name: &str,
198→    schema: &gurkha::DynamicLayerSchema,
199→    creator_did: &str,
200→    connected_peers: &[(String, String)],  // (did, role)
201→) -> Result<Vec<(String, String)>, String> {
202→    let mut permits = Vec::new();
203→
204→    match schema.grant {
205→        gurkha::GrantType::Role => {
206→            // Role-granted: all peers with matching roles get access
207→            for (did, role) in connected_peers {
208→                if let Some(perms) = schema.role_permissions.get(role) {
209→                    match permit_issuer.issue_layer_permit(did, layer_name, perms.clone(), None) {
210→                        Ok((token, _cid)) => {
211→                            info!(
212→                                page_id = %page_id,
213→                                layer = %layer_name,
214→                                recipient = %did,
215→                                role = %role,
216→                                "Issued role-based layer permit"
217→                            );
218→                            permits.push((did.clone(), token));
219→                        }
220→                        Err(e) => {
221→                            warn!(
222→                                page_id = %page_id,
223→                                layer = %layer_name,
224→                                recipient = %did,
225→                                error = %e,
226→                                "Failed to issue layer permit"
227→                            );
228→                        }
229→                    }
230→                }
231→            }
232→        }
233→        gurkha::GrantType::Explicit => {
234→            // Explicit-granted: authority-driven only (creator -> node permits).
235→            for (audience_did, _role) in connected_peers {
236→                let Some((config, intent_cid)) = authority_layer_config_and_intent(
237→                    permit_issuer,
238→                    audience_did,
239→                    layer_name,
240→                    page_id,
241→                ) else {
242→                    continue;
243→                };
244→
245→                match permit_issuer.issue_layer_permit(
246→                    audience_did,
247→                    layer_name,
248→                    config,
249→                    Some(&intent_cid),
250→                ) {
251→                    Ok((token, _cid)) => {
252→                        info!(
253→                            page_id = %page_id,
254→                            layer = %layer_name,
255→                            audience = %audience_did,
256→                            creator = %creator_did,
257→                            "Issued explicit layer permit from authority"
258→                        );
259→                        permits.push((audience_did.clone(), token));
260→                    }
261→                    Err(e) => {
262→                        warn!(
263→                            page_id = %page_id,
264→                            layer = %layer_name,
265→                            audience = %audience_did,
266→                            error = %e,
267→                            "Failed to issue explicit layer permit from authority"
268→                        );
269→                    }
270→                }
271→            }
272→        }
273→    }
274→
275→    Ok(permits)
276→}
277→
278→/// Find matching dynamic schema for a layer received from a peer
279→///
280→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
281→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
282→pub fn find_matching_dynamic_schema<'a>(
283→    permit: &'a gurkha::Permit,
284→    layer_name: &str,
285→    page_id: &str,
286→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
287→    let schemas = permit.dynamic_layer_schemas();
288→    if schemas.is_empty() {
289→        return None;
290→    }
291→
292→    // Strip page_id prefix to get bare layer path
293→    let page_prefix = format!("{}/", page_id);
294→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
295→
296→    let path_parts: Vec<&str> = bare_path.split('/').collect();
297→
298→    // Path must have at least 3 segments: prefix/did/id[/suffix]
299→    if path_parts.len() < 3 {
300→        return None;
301→    }
302→
303→    // Second segment should be a DID (the creator)
304→    let potential_creator = path_parts[1];
305→    if !potential_creator.starts_with("did:") {
306→        return None;
307→    }
308→
309→    // Try each schema pattern
310→    for (schema_key, schema) in schemas {
311→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
312→
313→        // Dynamic path has one extra segment (DID) compared to pattern
314→        if path_parts.len() != pattern_parts.len() + 1 {
315→            continue;
316→        }
317→
318→        // First segment must match literally
319→        if path_parts[0] != pattern_parts[0] {
320→            continue;
321→        }
322→
323→        // path[2..] must match pattern[1..] (with {id} as wildcard)
324→        let mut matched = true;
325→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
326→            if *pat_seg != "{id}" && path_seg != pat_seg {
327→                matched = false;
328→                break;
329→            }
330→        }
331→
332→        if matched {
333→            return Some((schema_key, schema, potential_creator.to_string()));
334→        }
335→    }
336→
337→    None
338→}
339→
340→/// Validate that a layer path created by a peer matches their DID (namespace security)
341→///
342→/// **Context**: Node receives a new layer from a peer. Before accepting, verify
343→/// that the creator's DID is in the layer path (prevents namespace forgery).
344→///
345→/// **Returns**: true if the layer path contains the sender's DID
346→pub fn validate_creator_namespace(layer_name: &str, page_id: &str, sender_did: &str) -> bool {
347→    let page_prefix = format!("{}/", page_id);
348→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
349→
350→    // The creator's DID must be the second segment in the path
351→    let parts: Vec<&str> = bare_path.split('/').collect();
352→    if parts.len() < 2 {
353→        return false;
354→    }
355→
356→    parts[1] == sender_did
357→}
358→
359→/// Handle AddLayerAccess message
360→///
361→/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
362→/// **We do**: Validate capability, require authority permit, issue permit if peer is subscribed
363→pub async fn handle_add_layer_access(
364→    state: &ScribeState,
365→    layer_name: &str,
366→    did: &str,
367→) -> Result<(), String> {
368→    // 1. Check our permit has manage_layer_access capability
369→    let permit = state.our_permit.as_ref().ok_or_else(|| {
370→        warn!(page_id = %state.page_id, layer = %layer_name, audience = %did, "AddLayerAccess rejected: missing our_permit");
371→        "No permit".to_string()
372→    })?;
373→    if !permit.can_manage_layer_access() {
374→        warn!(
375→            page_id = %state.page_id,
376→            layer = %layer_name,
377→            audience = %did,
378→            "AddLayerAccess rejected: missing manage_layer_access capability"
379→        );
380→        return Err("No manage_layer_access capability".into());
381→    }
382→
383→    // 2. Resolve schema/config and permit issuer
384→    let issuer = state.permit_issuer.as_ref().ok_or_else(|| {
385→        warn!(
386→            page_id = %state.page_id,
387→            layer = %layer_name,
388→            audience = %did,
389→            "AddLayerAccess rejected: no permit issuer (not node mode)"
390→        );
391→        "No permit issuer (not node mode)".to_string()
392→    })?;
393→    let (_schema_key, schema, _creator) = find_matching_dynamic_schema(permit, layer_name, &state.page_id)
394→        .ok_or_else(|| {
395→            warn!(
396→                page_id = %state.page_id,
397→                layer = %layer_name,
398→                audience = %did,
399→                "AddLayerAccess rejected: layer does not match dynamic schema"
400→            );
401→            "Layer does not match any dynamic schema".to_string()
402→        })?;
403→    if schema.grant != gurkha::GrantType::Explicit {
404→        warn!(
405→            page_id = %state.page_id,
406→            layer = %layer_name,
407→            audience = %did,
408→            "AddLayerAccess rejected: schema grant is not explicit"
409→        );
410→        return Err("AddLayerAccess only applies to explicit dynamic schemas".into());
411→    }
412→
413→    let (config, intent_cid, source) = if let Some((cfg, cid)) = authority_layer_config_and_intent(
414→        issuer.as_ref(),
415→        did,
416→        layer_name,
417→        &state.page_id,
418→    ) {
419→        (cfg, Some(cid), "authority")
420→    } else {
421→        let cfg = schema
422→            .permissions
423→            .clone()
424→            .ok_or_else(|| "Explicit schema missing permissions and no authority permit present".to_string())?;
425→        warn!(
426→            page_id = %state.page_id,
427→            layer = %layer_name,
428→            audience = %did,
429→            "No layer authority permit found; issuing access from explicit schema permissions"
430→        );
431→        (cfg, None, "schema_permissions")
432→    };
433→
434→    // 3. Issue permit (stored by coordinator even if peer is offline)
435→    let mut new_permits = Vec::new();
436→    match issuer.issue_layer_permit(did, layer_name, config, intent_cid.as_deref()) {
437→        Ok((token, _cid)) => {
438→            info!(
439→                page_id = %state.page_id,
440→                layer = %layer_name,
441→                audience = %did,
442→                source = %source,
443→                "Issued layer permit via AddLayerAccess"
444→            );
445→            new_permits.push((did.to_string(), token));
446→        }
447→        Err(e) => {
448→            warn!(error = %e, "Failed to issue layer permit for AddLayerAccess");
449→        }
450→    }
451→
452→    // 4. Authorize DID on the LayerUnit (if permit was issued)
453→    if let Some((recipient_did, _token)) = new_permits.first() {
454→        let bare_name = crate::state::normalize_layer_name(layer_name, &state.page_id);
455→        if let Some(unit) = state.units.get(&bare_name) {
456→            unit.authorize_did(recipient_did);
457→            state.emit_layer_auth_capture(&bare_name, recipient_did, "authorized_add_access");
458→        }
459→    }
460→
461→    // 5. Emit LayerAccessChanged for Coordinator to store/distribute permit
462→    if !new_permits.is_empty() {
463→        if let Some(ref sync_event_tx) = state.sync_event_tx {
464→            let event = crate::SyncEvent::LayerAccessChanged {
465→                page_id: state.page_id.clone(),
466→                layer_name: layer_name.to_string(),
467→                permits: new_permits,
468→            };
469→            state.emit_sync_event_capture(&event);
470→            if let Err(e) = sync_event_tx.send(event).await {
471→                warn!(error = %e, "Failed to emit LayerAccessChanged");
472→            }
473→        }
474→    }
475→
476→    Ok(())
477→}
478→
479→/// Handle RemoveLayerAccess message
480→///
481→/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
482→/// **We do**: Validate capability, reject metadata-era revoke path
483→pub fn handle_remove_layer_access(
484→    state: &ScribeState,
485→    layer_name: &str,
486→    did: &str,
487→) -> Result<(), String> {
488→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
489→    if !permit.can_manage_layer_access() {
490→        return Err("No manage_layer_access capability".into());
491→    }
492→
493→    let _ = layer_name;
494→    let _ = did;
495→    Err("RemoveLayerAccess is deprecated; rotate/revoke layer authority permits instead".to_string())
496→}
497→
498→fn authority_layer_config_and_intent(
499→    issuer: &dyn PermitIssuer,
500→    audience_did: &str,
501→    layer_name: &str,
502→    page_id: &str,
503→) -> Option<(gurkha::LayerConfig, String)> {
504→    let (_version, authority_token) = issuer
505→        .get_layer_authority_permit(audience_did, layer_name)
506→        .ok()
507→        .flatten()?;
508→
509→    let parsed = gurkha::Permit::from_token(&authority_token).ok()?;
510→    let config = if let Some(c) = parsed.layers().get(layer_name) {
511→        c.clone()
512→    } else {
513→        let bare = crate::state::normalize_layer_name(layer_name, page_id);
514→        parsed.layers().get(&bare)?.clone()
515→    };
516→
517→    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok()?;
518→    Some((config, intent_cid))
519→}
